# Generated by Cursor (plan: bracket acronyms (MPSC), (NRDC) -> letter-by-letter)
"""Scan for parenthesized 2+ letter acronyms (all-caps or 2+ caps); spell letter-by-letter. Excludes (i)-(xii)."""

import re

# Roman numerals (i)-(xii) handled by roman_parens; exclude from bracket_acronym.
_ROMAN_PARENS_INNER = frozenset(
    {"i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x", "xi", "xii"}
)

BRACKET_ACRONYM_RE = re.compile(r"\(\s*([A-Za-z]{2,})\s*\)")


def _is_bracket_acronym(inner: str) -> bool:
    """Return True if 2+ chars, not roman i-xii, and all-caps or 2+ capitals. Edited by Cursor."""
    s = inner.strip()
    if len(s) < 2:
        return False
    if s.lower() in _ROMAN_PARENS_INNER:
        return False
    caps = sum(1 for c in s if c.isupper())
    return s.isupper() or caps >= 2


def scan_turn_bracket_acronym(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (bracket_acronym, start_index, full_span, path_str) for (MPSC), (NRDC), etc."""
    result: list[tuple[str, int, str, str]] = []
    for m in BRACKET_ACRONYM_RE.finditer(text):
        inner = m.group(1).strip()
        if _is_bracket_acronym(inner):
            full_span = m.group(0)
            result.append(("bracket_acronym", m.start(), full_span, path_str))
    return result
